import{_ as i,C as o,c,o as t,aa as d,G as a}from"./chunks/framework.Cn7WEiMX.js";const u=JSON.parse('{"title":"BoxRenderer 类","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/developers/classes/boxrenderer-class.md","filePath":"wiki/Dynmap/developers/classes/boxrenderer-class.md"}'),s={name:"wiki/Dynmap/developers/classes/boxrenderer-class.md"};function n(p,e,h,_,m,x){const r=o("NolebaseGitContributors"),l=o("NolebaseGitChangelog");return t(),c("div",null,[e[0]||(e[0]=d('<h1 id="boxrenderer-类" tabindex="-1">BoxRenderer 类 <a class="header-anchor" href="#boxrenderer-类" aria-label="Permalink to &quot;BoxRenderer 类&quot;">​</a></h1> <p>BoxRenderer 类是一个简单的着色器，用于创建正常实心方块（仅纹理有差别），但在 XYZ 轴上有缩减。与大部分自定义着色器不同的是，应用于模型的纹理设置与一般的实心方块相同。注意：这是用于实现立方体模型的自定义着色器。</p> <h2 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h2> <ul><li><code>xmin</code> - 决定了方块 X 轴切割的最小值：设置后，方块的 X 轴将会从给定值处起始（默认值则为 0.0，即不偏移）。</li> <li><code>xmax</code> - 决定了方块 X 轴切割的最大值：设置后，方块的 X 轴将会在给定值处结束（默认值则为 0.0，即不偏移）。</li> <li><code>ymin</code> - 决定了方块 Y 轴切割的最小值：设置后，方块的 Y 轴将会从给定值处起始（默认值则为 0.0，即不偏移）。</li> <li><code>ymax</code> - 决定了方块 Y 轴切割的最大值：设置后，方块的 Y 轴将会在给定值处结束（默认值则为 0.0，即不偏移）。</li> <li><code>zmin</code> - 决定了方块 Z 轴切割的最小值：设置后，方块的 Z 轴将会从给定值处起始（默认值则为 0.0，即不偏移）。</li> <li><code>zmax</code> - 决定了方块 Z 轴切割的最大值：设置后，方块的 Z 轴将会在给定值处结束（默认值则为 0.0，即不偏移）。</li></ul> <h2 id="需要纹理的补丁" tabindex="-1">需要纹理的补丁 <a class="header-anchor" href="#需要纹理的补丁" aria-label="Permalink to &quot;需要纹理的补丁&quot;">​</a></h2> <ul><li><code>patch0</code> - 负向 X 轴侧（西）</li> <li><code>patch1</code> - 负向 Y 轴侧（底）</li> <li><code>patch2</code> - 负向 Z 轴侧（北）</li> <li><code>patch3</code> - 正向 X 轴侧（东）</li> <li><code>patch4</code> - 正向 Y 轴侧（顶）</li> <li><code>patch5</code> - 正向 Z 轴侧（南）</li></ul> ',12)),a(r),a(l)])}const f=i(s,[["render",n]]);export{u as __pageData,f as default};
